<?php get_header(); ?>
<div class="bhp-shop wrap"><header class="bhp-shop-head"><div><span class="bhx-overline">فروشگاه بهاران</span><h1><?php woocommerce_page_title();?></h1><?php do_action('woocommerce_archive_description');?></div><div class="bhp-shop-count"><?php woocommerce_result_count();?></div></header>

<div class="bhp-shop-layout"><aside class="bhp-filters"><form method="get" action="<?php echo esc_url(get_pagenum_link(1));?>"><div class="bhp-filter-title"><b>فیلتر محصولات</b><a href="<?php echo esc_url(wc_get_page_permalink('shop'));?>">پاک‌کردن</a></div><details open><summary>محدوده قیمت</summary><div class="bhp-price-filter"><label>از<input name="min_price" type="number" min="0" value="<?php echo isset($_GET['min_price'])?esc_attr(wp_unslash($_GET['min_price'])):'';?>" placeholder="حداقل"></label><label>تا<input name="max_price" type="number" min="0" value="<?php echo isset($_GET['max_price'])?esc_attr(wp_unslash($_GET['max_price'])):'';?>" placeholder="حداکثر"></label></div></details><?php if(taxonomy_exists('pa_brand')):$brands=get_terms(['taxonomy'=>'pa_brand','hide_empty'=>true]);if($brands&&!is_wp_error($brands)):?><details open><summary>برند</summary><select name="filter_pa_brand" class="bhp-brand-select"><option value="">همه‌ی برندها</option><?php foreach($brands as $brand):?><option value="<?php echo esc_attr($brand->slug);?>" <?php selected(isset($_GET['filter_pa_brand'])&&sanitize_title(wp_unslash($_GET['filter_pa_brand']))===$brand->slug);?>><?php echo esc_html($brand->name);?></option><?php endforeach;?></select></details><?php endif;endif;?><details><summary>دسته‌بندی</summary><div class="bhp-check-list"><?php $cats=get_terms(['taxonomy'=>'product_cat','hide_empty'=>true,'parent'=>0]);if($cats&&!is_wp_error($cats))foreach($cats as $cat):?><a href="<?php echo esc_url(get_term_link($cat));?>"><?php echo esc_html($cat->name);?><small><?php echo intval($cat->count);?></small></a><?php endforeach;?></div></details><label class="bhp-stock-filter"><input type="checkbox" name="filter_stock_status" value="instock" <?php checked(isset($_GET['filter_stock_status'])&&$_GET['filter_stock_status']==='instock');?>> فقط کالاهای موجود</label><?php foreach($_GET as $k=>$v) if(in_array($k,['orderby','s','post_type'],true)) echo '<input type="hidden" name="'.esc_attr($k).'" value="'.esc_attr(sanitize_text_field(wp_unslash($v))).'">';?><button class="bhp-filter-submit" type="submit">اعمال فیلترها</button></form></aside><section class="bhp-shop-results"><div class="bhp-toolbar"><span><?php woocommerce_result_count();?></span><?php woocommerce_catalog_ordering();?></div><?php if(woocommerce_product_loop()):?><ul class="products columns-3"><?php while(have_posts()):the_post();wc_get_template_part('content','product');endwhile;?></ul><?php do_action('woocommerce_after_shop_loop');else:do_action('woocommerce_no_products_found');endif;?></section></div></div><?php get_footer(); ?>
